# -*- coding: utf-8 -*-
"""R73 S8 (B21+B22, 40 cases) blind predictions. Segmented append."""
import json, os
OUT = "/home/hatch/workspace/divination/benchmark/phase3/runs/round73/predictions"
os.makedirs(OUT, exist_ok=True)
TRIG = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
DATA = []
def add(cid, pred, basis, conf):
    DATA.append({"case_id": cid, "prediction_text": pred, "basis": basis,
                 "confidence": conf, "trigger": dict(TRIG)})
def flush(ids):
    got = [d["case_id"] for d in DATA]
    assert got == ids, (got, ids)
    for d in DATA:
        with open(os.path.join(OUT, d["case_id"] + ".json"), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
    print("wrote", len(DATA), got[0], "->", got[-1])
    DATA.clear()

